/**
 * Smart Aggregator: Prepares the payload and handles the 'trigger_judge' logic.
 * Uses string literals for node access to ensure n8n optimization.
 */

// 1. Initialize the storage for results
let aggregatedData = {
  source_chunks: "",
  summarizer_agent_output: null,
  quiz_agent_output: null,
  flashcard_agent_output: null,
  sate_extractor_output: null,
  trigger_judge: false
};

// Track how many agents successfully returned data
let completedCount = 0;
const totalRequired = 4; // Total number of agents we are waiting for

// 2. Extract inputs safely using string literals
try {
  const node = $('Summarizer Agent').first();
  if (node && node.json) {
    aggregatedData.summarizer_agent_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

try {
  const node = $('Quiz Agent').first();
  if (node && node.json) {
    aggregatedData.quiz_agent_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

try {
  const node = $('Flashcard Agent').first();
  if (node && node.json) {
    aggregatedData.flashcard_agent_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

try {
  const node = $('Sate Extractor').first();
  if (node && node.json) {
    aggregatedData.sate_extractor_output = node.json.output || node.json;
    completedCount++;
  }
} catch (e) {}

// Extract source content (usually doesn't count towards the agent completion total)
try {
  aggregatedData.source_chunks = $('RAG Knowledge Base (Insert)').first().json.pageContent || "";
} catch (e) {
  aggregatedData.source_chunks = "Source content unavailable";
}

// 3. Final Logic: Trigger Judge only if all required tasks are done
if (completedCount === totalRequired) {
  aggregatedData.trigger_judge = true;
}

// 4. Return the aggregated data for the following IF node
return [{
  json: aggregatedData
}];

/**
 * n8n Code Node (JavaScript)
 * Mode: Run Once for All Items
 */

// 1. Access the incoming data correctly
// Since it's "Run Once for All Items", we access the first item in the input array
const items = $input.all();
if (items.length === 0) return []; // Guard against empty input

const input_data = items[0].json;

// 2. Extract User Preferences
const prefs = input_data.user_preferences || {
    "summary": true,
    "quiz": true,
    "flashcards": true
};

// 3. Initialize Statuses based on Preferences // change to check at first if thier values are done or not
let current_summary = prefs.summary ? "PENDING" : "SKIPPED";
let current_quiz = prefs.quiz ? "PENDING" : "SKIPPED";
let current_flashcards = prefs.flashcards ? "PENDING" : "SKIPPED";
let pack_approved = false;
let latest_feedback = "";

// 4. EXTRACTOR LOOKBACK
try {
    // Reference the 'Sate Extractor' node's data
    // const extractor_data = $('Sate Extractor').first().json;
    const last_step = $('Sate Extractor').first().json.next_step//extractor_data.next_step;

    if (last_step === "SUMMARIZER") {
        current_summary = "DONE";
    } else if (last_step === "QUIZ_GEN") {
        current_quiz = "DONE";
    } else if (last_step === "FLASHCARD_GEN") {
        current_flashcards = "DONE";
    } else if (last_step === "FINALIZE") {
        pack_approved = true;
    } else {
        latest_feedback = last_step || "";
    }
} catch (e) {
    // Node not found or hasn't run yet
}

// 5. JUDGE OVERRIDE
try {
    const judge_output = $('Judge Agent').first().json;
    if (judge_output && judge_output.decisions) {
        const decisions = judge_output.decisions;

        const checkRevision = (currentStatus, key) => {
            const val = decisions[key];
            if (val === "REVISE") return "PENDING";
            if (val === "APPROVED") return "APPROVED";
            return currentStatus;
        };

        current_summary = checkRevision(current_summary, "summary");
        current_quiz = checkRevision(current_quiz, "quiz");
        current_flashcards = checkRevision(current_flashcards, "flashcards");

        latest_feedback = judge_output.revision_instructions || latest_feedback;
    }
} catch (e) {
    // Judge node data not available
}

// 6. Final State Construction
let content = input_data.pageContent || "";

const new_state = {
    summary_status: current_summary,
    quiz_status: current_quiz,
    flashcard_status: current_flashcards,
    pack_approved: pack_approved,
    latest_feedback: latest_feedback,
    pageContent: content,
    user_preferences: prefs
};

// Return as an array of items
return [{ json: new_state }];
